-- A long `AND` list whose operand is itself a long list the user parenthesized: 18.6's
-- `makeAndExpr` absorbs one at the start of the list and keeps one anywhere else as
-- a single nested operand, and pglet's balanced list (`Expr::bool_list`) renders each
-- the same way — the list root is where a nested list begins.
-- @setup
CREATE TABLE nl (a INT,
  CONSTRAINT nl_start CHECK ((a <> 100 AND a <> 101 AND a <> 102 AND a <> 103 AND a <> 104 AND a <> 105 AND a <> 106 AND a <> 107 AND a <> 108 AND a <> 109 AND a <> 110 AND a <> 111 AND a <> 112 AND a <> 113 AND a <> 114 AND a <> 115 AND a <> 116 AND a <> 117 AND a <> 118 AND a <> 119 AND a <> 120 AND a <> 121 AND a <> 122 AND a <> 123 AND a <> 124 AND a <> 125 AND a <> 126 AND a <> 127 AND a <> 128 AND a <> 129 AND a <> 130 AND a <> 131 AND a <> 132 AND a <> 133 AND a <> 134 AND a <> 135 AND a <> 136 AND a <> 137 AND a <> 138 AND a <> 139 AND a <> 140 AND a <> 141 AND a <> 142 AND a <> 143 AND a <> 144 AND a <> 145 AND a <> 146 AND a <> 147 AND a <> 148 AND a <> 149 AND a <> 150 AND a <> 151 AND a <> 152 AND a <> 153 AND a <> 154 AND a <> 155 AND a <> 156 AND a <> 157 AND a <> 158 AND a <> 159 AND a <> 160 AND a <> 161 AND a <> 162 AND a <> 163 AND a <> 164 AND a <> 165 AND a <> 166 AND a <> 167 AND a <> 168 AND a <> 169) AND a <> 0 AND a <> 1 AND a <> 2 AND a <> 3 AND a <> 4 AND a <> 5 AND a <> 6 AND a <> 7 AND a <> 8 AND a <> 9 AND a <> 10 AND a <> 11 AND a <> 12 AND a <> 13 AND a <> 14 AND a <> 15 AND a <> 16 AND a <> 17 AND a <> 18 AND a <> 19 AND a <> 20 AND a <> 21 AND a <> 22 AND a <> 23 AND a <> 24 AND a <> 25 AND a <> 26 AND a <> 27 AND a <> 28 AND a <> 29 AND a <> 30 AND a <> 31 AND a <> 32 AND a <> 33 AND a <> 34 AND a <> 35 AND a <> 36 AND a <> 37 AND a <> 38 AND a <> 39 AND a <> 40 AND a <> 41 AND a <> 42 AND a <> 43 AND a <> 44 AND a <> 45 AND a <> 46 AND a <> 47 AND a <> 48 AND a <> 49 AND a <> 50 AND a <> 51 AND a <> 52 AND a <> 53 AND a <> 54 AND a <> 55 AND a <> 56 AND a <> 57 AND a <> 58 AND a <> 59 AND a <> 60 AND a <> 61 AND a <> 62 AND a <> 63 AND a <> 64 AND a <> 65 AND a <> 66 AND a <> 67 AND a <> 68 AND a <> 69),
  CONSTRAINT nl_mid CHECK (a <> 0 AND a <> 1 AND a <> 2 AND a <> 3 AND a <> 4 AND a <> 5 AND a <> 6 AND a <> 7 AND a <> 8 AND a <> 9 AND a <> 10 AND a <> 11 AND a <> 12 AND a <> 13 AND a <> 14 AND a <> 15 AND a <> 16 AND a <> 17 AND a <> 18 AND a <> 19 AND a <> 20 AND a <> 21 AND a <> 22 AND a <> 23 AND a <> 24 AND a <> 25 AND a <> 26 AND a <> 27 AND a <> 28 AND a <> 29 AND a <> 30 AND a <> 31 AND a <> 32 AND a <> 33 AND a <> 34 AND (a <> 100 AND a <> 101 AND a <> 102 AND a <> 103 AND a <> 104 AND a <> 105 AND a <> 106 AND a <> 107 AND a <> 108 AND a <> 109 AND a <> 110 AND a <> 111 AND a <> 112 AND a <> 113 AND a <> 114 AND a <> 115 AND a <> 116 AND a <> 117 AND a <> 118 AND a <> 119 AND a <> 120 AND a <> 121 AND a <> 122 AND a <> 123 AND a <> 124 AND a <> 125 AND a <> 126 AND a <> 127 AND a <> 128 AND a <> 129 AND a <> 130 AND a <> 131 AND a <> 132 AND a <> 133 AND a <> 134 AND a <> 135 AND a <> 136 AND a <> 137 AND a <> 138 AND a <> 139 AND a <> 140 AND a <> 141 AND a <> 142 AND a <> 143 AND a <> 144 AND a <> 145 AND a <> 146 AND a <> 147 AND a <> 148 AND a <> 149 AND a <> 150 AND a <> 151 AND a <> 152 AND a <> 153 AND a <> 154 AND a <> 155 AND a <> 156 AND a <> 157 AND a <> 158 AND a <> 159 AND a <> 160 AND a <> 161 AND a <> 162 AND a <> 163 AND a <> 164 AND a <> 165 AND a <> 166 AND a <> 167 AND a <> 168 AND a <> 169) AND a <> 35 AND a <> 36 AND a <> 37 AND a <> 38 AND a <> 39 AND a <> 40 AND a <> 41 AND a <> 42 AND a <> 43 AND a <> 44 AND a <> 45 AND a <> 46 AND a <> 47 AND a <> 48 AND a <> 49 AND a <> 50 AND a <> 51 AND a <> 52 AND a <> 53 AND a <> 54 AND a <> 55 AND a <> 56 AND a <> 57 AND a <> 58 AND a <> 59 AND a <> 60 AND a <> 61 AND a <> 62 AND a <> 63 AND a <> 64 AND a <> 65 AND a <> 66 AND a <> 67 AND a <> 68 AND a <> 69),
  CONSTRAINT nl_end CHECK (a <> 0 AND a <> 1 AND a <> 2 AND a <> 3 AND a <> 4 AND a <> 5 AND a <> 6 AND a <> 7 AND a <> 8 AND a <> 9 AND a <> 10 AND a <> 11 AND a <> 12 AND a <> 13 AND a <> 14 AND a <> 15 AND a <> 16 AND a <> 17 AND a <> 18 AND a <> 19 AND a <> 20 AND a <> 21 AND a <> 22 AND a <> 23 AND a <> 24 AND a <> 25 AND a <> 26 AND a <> 27 AND a <> 28 AND a <> 29 AND a <> 30 AND a <> 31 AND a <> 32 AND a <> 33 AND a <> 34 AND a <> 35 AND a <> 36 AND a <> 37 AND a <> 38 AND a <> 39 AND a <> 40 AND a <> 41 AND a <> 42 AND a <> 43 AND a <> 44 AND a <> 45 AND a <> 46 AND a <> 47 AND a <> 48 AND a <> 49 AND a <> 50 AND a <> 51 AND a <> 52 AND a <> 53 AND a <> 54 AND a <> 55 AND a <> 56 AND a <> 57 AND a <> 58 AND a <> 59 AND a <> 60 AND a <> 61 AND a <> 62 AND a <> 63 AND a <> 64 AND a <> 65 AND a <> 66 AND a <> 67 AND a <> 68 AND a <> 69 AND (a <> 100 AND a <> 101 AND a <> 102 AND a <> 103 AND a <> 104 AND a <> 105 AND a <> 106 AND a <> 107 AND a <> 108 AND a <> 109 AND a <> 110 AND a <> 111 AND a <> 112 AND a <> 113 AND a <> 114 AND a <> 115 AND a <> 116 AND a <> 117 AND a <> 118 AND a <> 119 AND a <> 120 AND a <> 121 AND a <> 122 AND a <> 123 AND a <> 124 AND a <> 125 AND a <> 126 AND a <> 127 AND a <> 128 AND a <> 129 AND a <> 130 AND a <> 131 AND a <> 132 AND a <> 133 AND a <> 134 AND a <> 135 AND a <> 136 AND a <> 137 AND a <> 138 AND a <> 139 AND a <> 140 AND a <> 141 AND a <> 142 AND a <> 143 AND a <> 144 AND a <> 145 AND a <> 146 AND a <> 147 AND a <> 148 AND a <> 149 AND a <> 150 AND a <> 151 AND a <> 152 AND a <> 153 AND a <> 154 AND a <> 155 AND a <> 156 AND a <> 157 AND a <> 158 AND a <> 159 AND a <> 160 AND a <> 161 AND a <> 162 AND a <> 163 AND a <> 164 AND a <> 165 AND a <> 166 AND a <> 167 AND a <> 168 AND a <> 169)),
  CONSTRAINT nl_in3 CHECK (a <> 1 AND (a <> 100 AND a <> 101 AND a <> 102 AND a <> 103 AND a <> 104 AND a <> 105 AND a <> 106 AND a <> 107 AND a <> 108 AND a <> 109 AND a <> 110 AND a <> 111 AND a <> 112 AND a <> 113 AND a <> 114 AND a <> 115 AND a <> 116 AND a <> 117 AND a <> 118 AND a <> 119 AND a <> 120 AND a <> 121 AND a <> 122 AND a <> 123 AND a <> 124 AND a <> 125 AND a <> 126 AND a <> 127 AND a <> 128 AND a <> 129 AND a <> 130 AND a <> 131 AND a <> 132 AND a <> 133 AND a <> 134 AND a <> 135 AND a <> 136 AND a <> 137 AND a <> 138 AND a <> 139 AND a <> 140 AND a <> 141 AND a <> 142 AND a <> 143 AND a <> 144 AND a <> 145 AND a <> 146 AND a <> 147 AND a <> 148 AND a <> 149 AND a <> 150 AND a <> 151 AND a <> 152 AND a <> 153 AND a <> 154 AND a <> 155 AND a <> 156 AND a <> 157 AND a <> 158 AND a <> 159 AND a <> 160 AND a <> 161 AND a <> 162 AND a <> 163 AND a <> 164 AND a <> 165 AND a <> 166 AND a <> 167 AND a <> 168 AND a <> 169) AND a <> 4),
  CONSTRAINT nl_or_in_and CHECK (a <> 0 AND a <> 1 AND a <> 2 AND a <> 3 AND a <> 4 AND a <> 5 AND a <> 6 AND a <> 7 AND a <> 8 AND a <> 9 AND a <> 10 AND a <> 11 AND a <> 12 AND a <> 13 AND a <> 14 AND a <> 15 AND a <> 16 AND a <> 17 AND a <> 18 AND a <> 19 AND a <> 20 AND a <> 21 AND a <> 22 AND a <> 23 AND a <> 24 AND a <> 25 AND a <> 26 AND a <> 27 AND a <> 28 AND a <> 29 AND a <> 30 AND a <> 31 AND a <> 32 AND a <> 33 AND a <> 34 AND (a <> 300 OR a <> 301 OR a <> 302 OR a <> 303 OR a <> 304 OR a <> 305 OR a <> 306 OR a <> 307 OR a <> 308 OR a <> 309 OR a <> 310 OR a <> 311 OR a <> 312 OR a <> 313 OR a <> 314 OR a <> 315 OR a <> 316 OR a <> 317 OR a <> 318 OR a <> 319 OR a <> 320 OR a <> 321 OR a <> 322 OR a <> 323 OR a <> 324 OR a <> 325 OR a <> 326 OR a <> 327 OR a <> 328 OR a <> 329 OR a <> 330 OR a <> 331 OR a <> 332 OR a <> 333 OR a <> 334 OR a <> 335 OR a <> 336 OR a <> 337 OR a <> 338 OR a <> 339 OR a <> 340 OR a <> 341 OR a <> 342 OR a <> 343 OR a <> 344 OR a <> 345 OR a <> 346 OR a <> 347 OR a <> 348 OR a <> 349 OR a <> 350 OR a <> 351 OR a <> 352 OR a <> 353 OR a <> 354 OR a <> 355 OR a <> 356 OR a <> 357 OR a <> 358 OR a <> 359 OR a <> 360 OR a <> 361 OR a <> 362 OR a <> 363 OR a <> 364 OR a <> 365 OR a <> 366 OR a <> 367 OR a <> 368 OR a <> 369) AND a <> 35 AND a <> 36 AND a <> 37 AND a <> 38 AND a <> 39 AND a <> 40 AND a <> 41 AND a <> 42 AND a <> 43 AND a <> 44 AND a <> 45 AND a <> 46 AND a <> 47 AND a <> 48 AND a <> 49 AND a <> 50 AND a <> 51 AND a <> 52 AND a <> 53 AND a <> 54 AND a <> 55 AND a <> 56 AND a <> 57 AND a <> 58 AND a <> 59 AND a <> 60 AND a <> 61 AND a <> 62 AND a <> 63 AND a <> 64 AND a <> 65 AND a <> 66 AND a <> 67 AND a <> 68 AND a <> 69),
  CONSTRAINT nl_nest_start CHECK (((a <> 400 AND a <> 401 AND a <> 402 AND a <> 403 AND a <> 404 AND a <> 405 AND a <> 406 AND a <> 407 AND a <> 408 AND a <> 409 AND a <> 410 AND a <> 411 AND a <> 412 AND a <> 413 AND a <> 414 AND a <> 415 AND a <> 416 AND a <> 417 AND a <> 418 AND a <> 419 AND a <> 420 AND a <> 421 AND a <> 422 AND a <> 423 AND a <> 424 AND a <> 425 AND a <> 426 AND a <> 427 AND a <> 428 AND a <> 429 AND a <> 430 AND a <> 431 AND a <> 432 AND a <> 433 AND a <> 434 AND a <> 435 AND a <> 436 AND a <> 437 AND a <> 438 AND a <> 439 AND a <> 440 AND a <> 441 AND a <> 442 AND a <> 443 AND a <> 444 AND a <> 445 AND a <> 446 AND a <> 447 AND a <> 448 AND a <> 449 AND a <> 450 AND a <> 451 AND a <> 452 AND a <> 453 AND a <> 454 AND a <> 455 AND a <> 456 AND a <> 457 AND a <> 458 AND a <> 459 AND a <> 460 AND a <> 461 AND a <> 462 AND a <> 463 AND a <> 464 AND a <> 465 AND a <> 466 AND a <> 467 AND a <> 468 AND a <> 469) AND a <> 500 AND a <> 501 AND a <> 502 AND a <> 503 AND a <> 504 AND a <> 505 AND a <> 506 AND a <> 507 AND a <> 508 AND a <> 509 AND a <> 510 AND a <> 511 AND a <> 512 AND a <> 513 AND a <> 514 AND a <> 515 AND a <> 516 AND a <> 517 AND a <> 518 AND a <> 519 AND a <> 520 AND a <> 521 AND a <> 522 AND a <> 523 AND a <> 524 AND a <> 525 AND a <> 526 AND a <> 527 AND a <> 528 AND a <> 529 AND a <> 530 AND a <> 531 AND a <> 532 AND a <> 533 AND a <> 534 AND a <> 535 AND a <> 536 AND a <> 537 AND a <> 538 AND a <> 539 AND a <> 540 AND a <> 541 AND a <> 542 AND a <> 543 AND a <> 544 AND a <> 545 AND a <> 546 AND a <> 547 AND a <> 548 AND a <> 549 AND a <> 550 AND a <> 551 AND a <> 552 AND a <> 553 AND a <> 554 AND a <> 555 AND a <> 556 AND a <> 557 AND a <> 558 AND a <> 559 AND a <> 560 AND a <> 561 AND a <> 562 AND a <> 563 AND a <> 564 AND a <> 565 AND a <> 566 AND a <> 567 AND a <> 568 AND a <> 569) AND a <> 600 AND a <> 601 AND a <> 602 AND a <> 603 AND a <> 604 AND a <> 605 AND a <> 606 AND a <> 607 AND a <> 608 AND a <> 609 AND a <> 610 AND a <> 611 AND a <> 612 AND a <> 613 AND a <> 614 AND a <> 615 AND a <> 616 AND a <> 617 AND a <> 618 AND a <> 619 AND a <> 620 AND a <> 621 AND a <> 622 AND a <> 623 AND a <> 624 AND a <> 625 AND a <> 626 AND a <> 627 AND a <> 628 AND a <> 629 AND a <> 630 AND a <> 631 AND a <> 632 AND a <> 633 AND a <> 634 AND a <> 635 AND a <> 636 AND a <> 637 AND a <> 638 AND a <> 639 AND a <> 640 AND a <> 641 AND a <> 642 AND a <> 643 AND a <> 644 AND a <> 645 AND a <> 646 AND a <> 647 AND a <> 648 AND a <> 649 AND a <> 650 AND a <> 651 AND a <> 652 AND a <> 653 AND a <> 654 AND a <> 655 AND a <> 656 AND a <> 657 AND a <> 658 AND a <> 659 AND a <> 660 AND a <> 661 AND a <> 662 AND a <> 663 AND a <> 664 AND a <> 665 AND a <> 666 AND a <> 667 AND a <> 668 AND a <> 669));
-- @no-declared-types: 18.6 sends `name` (19) for `conname` and
--   `information_schema.character_data` for `check_clause`, where pglet sends `text`
--   (25) — pre-existing catalog-type modelling, not this fixture's subject.
-- @test
SELECT c.conname, pg_get_constraintdef(c.oid) AS def, k.check_clause
FROM pg_constraint c
JOIN information_schema.check_constraints k ON k.constraint_name = c.conname
WHERE c.conname LIKE 'nl\_%'
ORDER BY c.conname;
